        public static Color? DuckColor;
        public static float DuckWingMix = 0.14f;

        /// v6l T: перекрасить обычную утку на лету. Геометрия детерминирована — строим утку заново с текущими DuckColor/DuckWingMix
        /// и переносим цвета вершин в уже существующие меши (полная, LOD 1 и 2): все тела, держащие эти меши, меняются сразу.
        /// Возвращает число перекрашенных мешей (0 — меш ещё не строился или число вершин не совпало).
        public int RetintDuck()
        {
            _duckB[0] = null;   // кэш декора (DuckBuilder) пересоберётся с новым цветом
            int n = 0;
            var full = _single[(int)ModelId.Duck];
            if (full)
            {
                var b = new MeshBuilder();
                BuildDuck(b, false, new int[2]);
                n += CopyDuckColors(b, full);
            }
            for (int tier = 1; tier <= 2; tier++)
            {
                var lod = _duckLod[(tier - 1) * 2];
                if (!lod) continue;
                var b = new MeshBuilder();
                BuildDuck(b, false, null, true, tier);
                n += CopyDuckColors(b, lod);
            }
            return n;
        }

        static int CopyDuckColors(MeshBuilder b, Mesh target)
        {
            var tmp = b.ToMesh("DuckRetint", false);
            int ok = 0;
            if (tmp.vertexCount == target.vertexCount)
            {
                var cols = new List<Color>(tmp.vertexCount);
                tmp.GetColors(cols);
                target.SetColors(cols);
                target.UploadMeshData(false);
                ok = 1;
            }
            else Debug.LogWarning($"[PITT] duck retint: vertex count {tmp.vertexCount} != {target.vertexCount} ({target.name})");
            Object.Destroy(tmp);
            return ok;
        }
